          peach: 'خوخي'
        },
        bases: {
          white: 'قاعدة / صبغة بيضاء',
          blue: 'مركز أزرق',
          yellow: 'مركز أصفر',
          red: 'مركز أحمر',
          black: 'مركز أسود'
        }
      },
      fr: {
        dir: 'ltr',
        appTitle: 'Studio de Mélange de Couleurs',
        logoText: 'Studio de Mélange - Mesure par Bouchon',
        lblLang: 'Langue / Language:',
        lblUnit: 'Unité de mesure:',
        optCaps: 'Bouchons (Caps)',
